  /* ═══ remove with Undo ═══════════════════════════════════════════════
     removeWidget(u): takes the analysis off My dashboards and its stage, and offers Undo in the toast for 8 s (restored at the same position).
     The card's Remove button lives in App.card (app.js) — route it here: rm.onclick = () => Configurator.removeWidget(o.userWidget). */
  let lastRemoved = null;
  function removeWidget(u) {
    const list = S().userWidgets; const i = list.findIndex(x => x.id === u.id); if (i < 0) return;
    const [w] = list.splice(i, 1); lastRemoved = { w, i, at: Date.now() }; App.save(); App.render();
    App.toast(`“${w.name}” removed from your analyses.`); const t = document.getElementById('toast'); if (t) { clearTimeout(t._h); t.style.pointerEvents = 'auto'; const undo = H('button', 'btn xs pri'); undo.style.cssText = 'margin-left:10px;vertical-align:middle;pointer-events:auto'; undo.textContent = 'Undo'; undo.onclick = () => { undoRemove(); t.style.opacity = '0'; t.style.pointerEvents = ''; }; t.appendChild(undo); t._h = setTimeout(() => { t.style.opacity = '0'; t.style.pointerEvents = ''; }, 8000); }
    setTimeout(() => { if (lastRemoved && lastRemoved.w === w) lastRemoved = null; }, 8000);
  }
  function undoRemove() { if (!lastRemoved) return false; const { w, i } = lastRemoved; lastRemoved = null; const list = S().userWidgets; if (!list.some(x => x.id === w.id)) list.splice(Math.min(i, list.length), 0, w); App.save(); App.render(); App.toast(`“${w.name}” restored.`); return true; }

  /* ═══ export ═════════════════════════════════════════════════════════ */
  window.Configurator = { open, asDef, removeWidget, undoRemove, _internals: { evaluate, chartIssues, flipPlan, transposePlan, deriveName, norm, CHARTS, draftFromDef, state: () => st, paint: () => paint() } };
